const KOW_CONSTRUCTION_DURATION_MS=Object.freeze({refinery:7200000,steel_factory:6000000,food_factory:3600000,base_land:5400000,base_air:6000000,base_naval:5400000});
function applyAuthoritativeConstructionClock(rows,serverTime=now(),kind='structure'){
  const durationFor=row=>KOW_CONSTRUCTION_DURATION_MS[String(row&&row.type||'')]||0;
  if(!Array.isArray(rows))return [];
  return rows.map(row=>{
    if(!row||typeof row!=='object')return row;
    const duration=durationFor(row);
    if(!duration||row.isBuilding!==true)return row;
    const started=Number(row.startTime||row.started_at||0);
    if(!Number.isFinite(started)||started<=0)return row;
    if(serverTime-started>=duration){const done={...row,isBuilding:false,completedAt:started+duration};delete done.startTime;return done;}
    return {...row,isBuilding:true,startTime:started};
  });
}
function applyAuthoritativeBaseConstructionClock(rows,serverTime=now()){
  if(!Array.isArray(rows))return [];
  return rows.map(row=>{if(!row||typeof row!=='object'||row.isBuilding!==true)return row;const duration=KOW_CONSTRUCTION_DURATION_MS['base_'+String(row.type||'')];const started=Number(row.startTime||row.started_at||0);if(!duration||!Number.isFinite(started)||started<=0)return row;if(serverTime-started>=duration){const done={...row,isBuilding:false,completedAt:started+duration};delete done.startTime;return done;}return {...row,isBuilding:true,startTime:started};});
}
function json(data,status=200,origin='*'){return new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json; charset=utf-8',...corsHeaders(origin)}});}function err(message,status=400,origin='*',extra={}
){return json({ok:false,error:message,...extra},status,origin);}function now(){return Date.now();}function cleanUser(v){return String(v||'').trim().slice(0,40);}function safeInt(v,d=0){const n=parseInt(v,10);
return Number.isFinite(n)?n:d;}function clamp(n,min,max){return Math.max(min,Math.min(max,n));}function validCountry(c){return COUNTRIES.includes(c);}function weekStart(ts=now()){return ts-(ts%(7*24*3600*1000));
}function dayStart(ts=now()){return ts-(ts%(24*3600*1000));}async function tableColumns(db,table){if(!/^[A-Za-z_][A-Za-z0-9_]*$/.test(String(table)))throw new Error('نام جدول نامعتبر است: '+String(table));const r=await db.prepare(`PRAGMA table_info(${table})`).all();if(!r||!Array.isArray(r.results))throw new Error('خواندن ساختار جدول D1 ناموفق بود: '+table);return new Set(r.results.map(x=>x.name));}
async function addColumnIfMissing(db,table,col,sqlType){if(!/^[A-Za-z_][A-Za-z0-9_]*$/.test(String(table))||!/^[A-Za-z_][A-Za-z0-9_]*$/.test(String(col)))throw new Error('شناسه جدول/ستون برای مهاجرت نامعتبر است');const cols=await tableColumns(db,table);if(!cols.size)throw new Error('جدول موردنیاز مهاجرت وجود ندارد: '+table);if(cols.has(col))return false;try{await db.prepare(`ALTER TABLE ${table} ADD COLUMN ${col} ${sqlType}`).run();}catch(error){const afterRace=await tableColumns(db,table);if(afterRace.has(col))return false;throw new Error('افزودن ستون '+table+'.'+col+' ناموفق بود: '+String(error&&error.message||error));}const verified=await tableColumns(db,table);if(!verified.has(col))throw new Error('ستون پس از مهاجرت در D1 تأیید نشد: '+table+'.'+col);return true;}async function ensureNavalFleetReadSchema(db){
  await db.prepare(`CREATE TABLE IF NOT EXISTS naval_fleets (
    id TEXT PRIMARY KEY, username TEXT NOT NULL, server INTEGER NOT NULL DEFAULT 1,
    country_key TEXT, type TEXT NOT NULL DEFAULT 'ship', model TEXT,
    count INTEGER NOT NULL DEFAULT 1, lat REAL NOT NULL DEFAULT 0, lng REAL NOT NULL DEFAULT 0,
    target_lat REAL, target_lng REAL, status TEXT NOT NULL DEFAULT 'idle',
    radar_km REAL NOT NULL DEFAULT 300, last_update INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL DEFAULT 0
  )`).run();
  const required=[
    ['model','TEXT'],['radar_km','REAL NOT NULL DEFAULT 300'],['last_update','INTEGER NOT NULL DEFAULT 0'],
    ['created_at','INTEGER NOT NULL DEFAULT 0'],['origin_lat','REAL'],['origin_lng','REAL'],
    ['route_json','TEXT'],['route_index','INTEGER DEFAULT 0'],['route_distance_km','REAL DEFAULT 0'],
    ['progress_km','REAL DEFAULT 0'],['move_started_at','INTEGER'],['move_eta','INTEGER'],
    ['move_duration_ms','INTEGER DEFAULT 0'],['home_base_id','TEXT'],['group_id','TEXT'],
    ['fuel','REAL DEFAULT 0'],['fuel_capacity','REAL DEFAULT 250'],['fuel_initialized','INTEGER DEFAULT 0'],
    ['integrity','REAL DEFAULT 100'],['max_integrity','REAL DEFAULT 100'],['repair_until','INTEGER'],
    ['food','REAL DEFAULT 0'],['mission_status',"TEXT DEFAULT 'none'"],
    ['mission_target_fleet_id','TEXT'],['mission_target_username','TEXT'],['market_escort_shipment_id','TEXT'],
    ['updated_at','INTEGER'],['cargo_json','TEXT'],['cargo_barrels','REAL DEFAULT 0'],['escort_fleet_id','TEXT']
  ];
  let columns=await tableColumns(db,'naval_fleets');
  if(!columns.size)throw new Error('جدول naval_fleets پس از ایجاد در D1 قابل خواندن نیست');
  for(const [column,type] of required){
    if(columns.has(column))continue;
    await addColumnIfMissing(db,'naval_fleets',column,type);
    columns=await tableColumns(db,'naval_fleets');
  }
  const missing=required.map(([column])=>column).filter(column=>!columns.has(column));
  if(missing.length)throw new Error('ستون‌های ضروری ناوگان در D1 موجود نیستند: '+missing.join(', '));
  await db.prepare(`CREATE TABLE IF NOT EXISTS naval_berth_assignments (site_id INTEGER NOT NULL,slot_index INTEGER NOT NULL,fleet_id TEXT NOT NULL UNIQUE,username TEXT NOT NULL,server INTEGER NOT NULL,lat REAL NOT NULL,lng REAL NOT NULL,assigned_at INTEGER NOT NULL,PRIMARY KEY(site_id,slot_index))`).run();
  await db.prepare(`CREATE TABLE IF NOT EXISTS naval_berth_queue (id INTEGER PRIMARY KEY AUTOINCREMENT,site_id INTEGER NOT NULL,fleet_id TEXT NOT NULL UNIQUE,username TEXT NOT NULL,server INTEGER NOT NULL,created_at INTEGER NOT NULL)`).run();
}
