    if(radarA>0&&dd<=radarA)await createRadarAlert(env,server,a.username,b.username,'naval',b.id,Number(b.lat),Number(b.lng));
    if(radarB>0&&dd<=radarB)await createRadarAlert(env,server,b.username,a.username,'naval',a.id,Number(a.lat),Number(a.lng));
    const artilleryA=(a.type==='warship'||MODEL_META[a.model]?.baseUnit==='warship')&&weaponA>0&&Number(MODEL_META[a.model]?.damage||0)>0;
    const artilleryB=(b.type==='warship'||MODEL_META[b.model]?.baseUnit==='warship')&&weaponB>0&&Number(MODEL_META[b.model]?.damage||0)>0;
