function factoryCategory(key,siteType='factory',gameType=''){const k=(String(key||'')+' '+String(gameType||'')).toLowerCase();if(siteType==='shipyard'||/(shipyard|naval|dock|کشتی|ship|carrier|oil_tanker|warship)/i.test(k)||/(naval|sea|navy)/i.test(k))return 'naval';if(/missile|موشک|rocket|defense_ammo|air_defense|پدافند/i.test(k))return 'missile';if(/jet|fighter|drone|helicopter|air|airport|airbase|recon|جنگنده|هوایی|هلیکوپتر|پهپاد/i.test(k))return 'air';if(/soldier|tank|ground|زمینی|launcher|لانچر/i.test(k))return 'ground';return 'unclassified';}
