async function handleFactoryState(request,env,u){
 const server=clamp(safeInt(u.server,1),1,1000),username=u.username;
 // Strict read-only path: no locks, production ticks, schema migration, canonical-key
 // rewrites, or active-model writes are allowed while a panel is merely being read.
 const lines=(await env.DB.prepare(`SELECT f.factory_key,f.model,f.sample_count,f.queued,f.produced,f.last_tick,f.queue_order_at,f.created_at,gs.id AS site_id,gs.site_key,gs.site_type,gs.game_type,gs.integrity,gs.max_integrity,COALESCE(cap.occupied,0) AS occupied,${KOW_TIMING.factoryCapacity} AS capacity FROM factory_model_lines f LEFT JOIN game_sites gs ON gs.server=f.server AND gs.owner_username=f.username AND ((gs.site_type='shipyard' AND f.factory_key='shipyard_'||gs.id) OR (gs.site_type='factory' AND f.factory_key=gs.site_key)) LEFT JOIN (SELECT username,server,factory_key,SUM(queued+produced) AS occupied FROM factory_model_lines WHERE username=? AND server=? GROUP BY username,server,factory_key) cap ON cap.username=f.username AND cap.server=f.server AND cap.factory_key=f.factory_key WHERE f.username=? AND f.server=? ORDER BY f.factory_key,f.created_at,f.model`).bind(username,server,username,server).all()).results||[];
 // Include un-migrated legacy lines in the response without changing D1. The next
 // explicit POST /factory/tick migrates them in one INSERT..SELECT statement.
 const legacy=(await env.DB.prepare('SELECT factory_key,model,sample_count,queued,produced,last_tick FROM factory_lines WHERE username=? AND server=? AND model IS NOT NULL').bind(username,server).all()).results||[];
 const present=new Set(lines.map(x=>String(x.factory_key)+'::'+String(x.model)));
 for(const old of legacy){const k=String(old.factory_key)+'::'+String(old.model);if(present.has(k)||!MODEL_META[String(old.model)])continue;lines.push({factory_key:String(old.factory_key),model:String(old.model),sample_count:Math.max(1,safeInt(old.sample_count,1)),queued:Math.max(0,safeInt(old.queued)),produced:Math.max(0,safeInt(old.produced)),last_tick:safeInt(old.last_tick,now()),queue_order_at:safeInt(old.last_tick,now()),created_at:safeInt(old.last_tick,now()),occupied:Math.max(0,safeInt(old.queued)+safeInt(old.produced)),capacity:KOW_TIMING.factoryCapacity,legacy:true});}
 const activeRows=(await env.DB.prepare('SELECT factory_key,model FROM factory_active_models WHERE username=? AND server=?').bind(username,server).all()).results||[];
 const activeByKey=new Map(activeRows.map(x=>[String(x.factory_key),String(x.model||'')]));
 const legacyActive=new Map(legacy.filter(x=>x.model&&MODEL_META[String(x.model)]).map(x=>[String(x.factory_key),String(x.model)]));
 const lineGroups=new Map();for(const line of lines){const key=String(line.factory_key);if(!lineGroups.has(key))lineGroups.set(key,[]);lineGroups.get(key).push(line);}
 const activeModels=[];for(const [key,candidates] of lineGroups){let model=activeByKey.get(key)||'';if(!model||!candidates.some(x=>String(x.model)===model)){model=legacyActive.get(key)&&candidates.some(x=>String(x.model)===legacyActive.get(key))?legacyActive.get(key):(candidates.find(x=>safeInt(x.queued)+safeInt(x.produced)>0)||candidates[0]||{}).model||'';}if(model)activeModels.push({factory_key:key,model:String(model)});}
 const queueByFactory=new Map();for(const row of lines.filter(x=>safeInt(x.queued)>0).sort((a,b)=>String(a.factory_key).localeCompare(String(b.factory_key))||safeInt(a.queue_order_at||a.last_tick)-safeInt(b.queue_order_at||b.last_tick)||safeInt(a.created_at)-safeInt(b.created_at)||String(a.model).localeCompare(String(b.model)))){const key=String(row.factory_key);if(!queueByFactory.has(key))queueByFactory.set(key,[]);queueByFactory.get(key).push(row);}for(const [key,queue] of queueByFactory){for(let i=0;i<queue.length;i++){const row=queue[i],interval=factoryUnitIntervalMs(row.model,row),rowStart=safeInt(row.last_tick,now()),firstCompletion=rowStart+interval;row.queuePosition=i+1;row.queueStartAt=rowStart;row.unitDurationMs=interval;row.nextCompletionAt=firstCompletion;row.nextUnitRemainingMs=Math.max(0,firstCompletion-now());row.queueFinishAt=rowStart+Math.max(1,safeInt(row.queued))*interval;row.independentLine=true;}}
 return json({ok:true,lines,activeModels,inventory:await modelInventory(env,username,server),models:MODEL_META,equipmentPerformance:EQUIPMENT_PERFORMANCE,server,capacity:KOW_TIMING.factoryCapacity,serverNow:now(),readOnly:true},200);
}
