const RESOURCE_STORAGE_TYPES={oil:['oil_tank','warehouse'],steel:['steel_warehouse','warehouse'],food:['food_warehouse','warehouse']};
const RESOURCE_STORAGE_CAPACITY={oil:KOW_TIMING.oilTankCapacity,steel:KOW_TIMING.steelWarehouseCapacity,food:KOW_TIMING.foodWarehouseCapacity};const GENERIC_WAREHOUSE_RESOURCE_CAPACITY=1000;
async function ensureOwnedResourceStorageRows(env,username,server){
 const sites=(await env.DB.prepare("SELECT id,site_type FROM game_sites WHERE server=? AND owner_username=? AND integrity>0 AND site_type IN ('warehouse','oil_tank','steel_warehouse','food_warehouse') ORDER BY id").bind(server,username).all()).results||[];if(!sites.length)return 0;
 const ids=sites.map(x=>safeInt(x.id)),existing=[];for(let i=0;i<ids.length;i+=300){const part=ids.slice(i,i+300);const rows=(await env.DB.prepare('SELECT site_id,resource,capacity FROM site_resources WHERE site_id IN ('+part.map(()=>'?').join(',')+')').bind(...part).all()).results||[];existing.push(...rows);}
 const byKey=new Map(existing.map(x=>[String(x.site_id)+':'+String(x.resource),x])),stmts=[];
 for(const site of sites){const type=String(site.site_type);const resources=type==='warehouse'?['oil','steel','food']:type==='oil_tank'?['oil']:type==='steel_warehouse'?['steel']:type==='food_warehouse'?['food']:[];for(const resource of resources){const key=String(site.id)+':'+resource,old=byKey.get(key);const capacity=type==='warehouse'?GENERIC_WAREHOUSE_RESOURCE_CAPACITY:RESOURCE_STORAGE_CAPACITY[resource];if(!old)stmts.push(env.DB.prepare('INSERT OR IGNORE INTO site_resources(site_id,resource,quantity,capacity,updated_at) VALUES(?,?,0,?,?)').bind(site.id,resource,capacity,now()));else if(Number(old.capacity||0)<=0)stmts.push(env.DB.prepare('UPDATE site_resources SET capacity=?,updated_at=? WHERE site_id=? AND resource=? AND capacity<=0').bind(capacity,now(),site.id,resource));}}
 for(let i=0;i<stmts.length;i+=80)await env.DB.batch(stmts.slice(i,i+80));return sites.length;
}
async function ownedResourceRows(env,username,server,resource){const types=RESOURCE_STORAGE_TYPES[String(resource)]||['warehouse'];return(await env.DB.prepare('SELECT sr.site_id,sr.resource,sr.quantity,sr.capacity,gs.country_key,gs.site_type FROM site_resources sr JOIN game_sites gs ON gs.id=sr.site_id WHERE gs.server=? AND gs.owner_username=? AND gs.integrity>0 AND sr.resource=? AND gs.site_type IN ('+types.map(()=>'?').join(',')+') ORDER BY CASE gs.site_type WHEN ? THEN 0 ELSE 1 END,gs.id').bind(server,username,resource,...types,types[0]).all()).results||[];}
async function ownedResourceTotals(env,username,server,resources=['oil','steel','food']){await ensureOwnedResourceStorageRows(env,username,server);const totals={};for(const resource of resources){const rows=await ownedResourceRows(env,username,server,resource);totals[resource]=rows.reduce((sum,row)=>sum+Math.max(0,Number(row.quantity)||0),0);}return totals;}
async function migrateLegacyResourcesToStorage(env,username,server){
 const initial=await env.DB.prepare('SELECT save_json FROM kow_saves WHERE username=? AND server=?').bind(username,server).first();if(!initial)return{migrated:{}};let initialSave;try{initialSave=JSON.parse(initial.save_json||'{}')}catch(_){return{migrated:{}};}if(!['oil','steel','food'].some(k=>Number(initialSave[k]||0)>0))return{migrated:{}};
 return await withGameLock(env,`resource-ledger:${server}:${username}`,async()=>{
  await ensureOwnedResourceStorageRows(env,username,server);
  const row=await env.DB.prepare('SELECT save_json FROM kow_saves WHERE username=? AND server=?').bind(username,server).first();if(!row)return{migrated:{}};
  let save;try{save=JSON.parse(row.save_json||'{}')}catch(_){return{migrated:{}};}
  const migrated={};
  for(const resource of ['oil','steel','food']){
   const legacy=Math.max(0,Number(save[resource])||0);if(legacy<=0)continue;
   const rows=await ownedResourceRows(env,username,server,resource);let remaining=legacy;const allocations=[];
   for(const storage of rows){const free=Math.max(0,Number(storage.capacity||0)-Number(storage.quantity||0));const amount=Math.min(remaining,free);if(amount>0){allocations.push({site_id:safeInt(storage.site_id),amount});remaining-=amount;}if(remaining<=1e-8)break;}
   const amount=legacy-remaining;if(amount<=1e-8)continue;
   const next={...save,[resource]:Math.max(0,legacy-amount)};next.server=server;const after=JSON.stringify(next),caseSql='CASE site_id '+allocations.map(()=> 'WHEN ? THEN ?').join(' ')+' ELSE 0 END',idsSql=allocations.map(()=>'?').join(',');
   const binds1=[];for(const a of allocations)binds1.push(a.site_id,a.amount);binds1.push(now(),resource,...allocations.map(a=>a.site_id));const binds2=[];for(const a of allocations)binds2.push(a.site_id,a.amount);
   const updateStorage=env.DB.prepare('UPDATE site_resources SET quantity=quantity+'+caseSql+',updated_at=? WHERE resource=? AND site_id IN ('+idsSql+') AND quantity+'+caseSql+'<=capacity').bind(...binds1,...binds2);
   const updateSave=env.DB.prepare('UPDATE kow_saves SET save_json=?,updated_at=? WHERE username=? AND server=? AND save_json=?').bind(after,now(),username,server,String(row.save_json));
   try{await env.DB.batch([updateStorage,env.DB.prepare('INSERT INTO resource_migration_guard(id) SELECT 1 WHERE changes()<>?').bind(allocations.length),updateSave,env.DB.prepare('INSERT INTO resource_migration_guard(id) SELECT 1 WHERE changes()<>1')]);save=next;row.save_json=after;migrated[resource]=amount;}
   catch(error){console.warn('KOW legacy resource migration deferred',username,resource,String(error&&error.message||error));break;}
  }
  return{migrated};
 },10000,30000);
}
async function withOwnedResourceDebit(env,username,server,costs,work){
 await migrateLegacyResourcesToStorage(env,username,server);
 const normalized={};for(const [resource,value] of Object.entries(costs||{})){const amount=Math.max(0,Number(value)||0);if(amount>0)normalized[String(resource)]=amount;}
 return withGameLock(env,`resource-ledger:${server}:${username}`,async()=>{const receipt=[];for(const [resource,amount] of Object.entries(normalized)){const rows=await ownedResourceRows(env,username,server,resource);let total=rows.reduce((sum,row)=>sum+Math.max(0,Number(row.quantity)||0),0);if(total+1e-8<amount){for(const done of receipt)await env.DB.prepare('UPDATE site_resources SET quantity=quantity+?,updated_at=? WHERE site_id=? AND resource=?').bind(done.amount,now(),done.site_id,done.resource).run().catch(()=>{});return{ok:false,error:`موجودی ${resource==='oil'?'نفت':resource==='steel'?'فولاد':resource==='food'?'غذا':resource} در انبارها و مخازن کافی نیست؛ موجودی واقعی: ${total.toFixed(2)}، موردنیاز: ${amount.toFixed(2)}`,resource,available:total,required:amount};}let remaining=amount;for(const row of rows){if(remaining<=1e-8)break;const take=Math.min(remaining,Math.max(0,Number(row.quantity)||0));if(take<=0)continue;const debit=await env.DB.prepare('UPDATE site_resources SET quantity=quantity-?,updated_at=? WHERE site_id=? AND resource=? AND quantity>=?').bind(take,now(),row.site_id,resource,take).run();if(!debit.meta||safeInt(debit.meta.changes)!==1){for(const done of receipt)await env.DB.prepare('UPDATE site_resources SET quantity=quantity+?,updated_at=? WHERE site_id=? AND resource=?').bind(done.amount,now(),done.site_id,done.resource).run().catch(()=>{});return{ok:false,error:'موجودی انبار هم‌زمان تغییر کرد؛ دوباره تلاش کن'};}receipt.push({site_id:row.site_id,resource,amount:take});remaining-=take;}}
 try{const result=await work(receipt);if(result&&result.ok===false){for(const done of receipt)await env.DB.prepare('UPDATE site_resources SET quantity=quantity+?,updated_at=? WHERE site_id=? AND resource=?').bind(done.amount,now(),done.site_id,done.resource).run();}return result;}catch(error){for(const done of receipt)await env.DB.prepare('UPDATE site_resources SET quantity=quantity+?,updated_at=? WHERE site_id=? AND resource=?').bind(done.amount,now(),done.site_id,done.resource).run().catch(()=>{});throw error;}},10000,30000);
}
async function activeOilEvents(env,server){return(await env.DB.prepare('SELECT * FROM oil_market_events WHERE server=? AND active=1 AND starts_at<=? AND (ends_at IS NULL OR ends_at>?) ORDER BY id DESC').bind(server,now(),now()).all()).results||[];
}const RESOURCE_PRODUCTION_RULES={oil:{industryKeys:['refinery','refinery_oil','oil_refinery'],intervalMs:10*60*1000,amount:5,warehouseTypes:['oil_tank','warehouse']},steel:{industryKeys:['steel_factory','steel_industry','steel_mill'],intervalMs:KOW_TIMING.steelProductionIntervalMs,amount:KOW_TIMING.steelProductionAmount,warehouseTypes:['steel_warehouse','warehouse']}
,food:{industryKeys:['food_factory','food_industry','food_plant'],intervalMs:KOW_TIMING.foodProductionIntervalMs,amount:KOW_TIMING.foodProductionAmount,warehouseTypes:['food_warehouse','warehouse']}
};function siteKeyMatchesProduction(siteKey,keys){const k=String(siteKey||'').toLowerCase();return keys.some(x=>k===x||k.startsWith(x+'_'));}
function productionSiteMatches(site,rule){let payload={};try{payload=JSON.parse(site.payload_json||'{}')}catch(_){}const candidates=[site.site_key,site.game_type,site.site_type,payload.type,payload.gameType,payload.kind,payload.structureType,payload.produces];return candidates.some(v=>siteKeyMatchesProduction(v,rule.industryKeys));}
async function resourceProductionTick(env,server){
  try{return await withGameLock(env,`resource-production:${server}`,async()=>{
    const t=now();
    const industries=(await env.DB.prepare("SELECT id,owner_username,country_key,site_key,game_type,site_type,payload_json FROM game_sites WHERE server=? AND integrity>0 AND site_type IN ('industry','factory') ORDER BY id").bind(server).all()).results||[];
    if(!industries.length)return{ok:true,processed:0};
    let processed=0,produced={oil:0,steel:0,food:0};
    for(const[resource,rule]of Object.entries(RESOURCE_PRODUCTION_RULES)){
      const matches=industries.filter(ind=>productionSiteMatches(ind,rule));
      if(!matches.length)continue;
      const warehouses=(await env.DB.prepare("SELECT gs.id,gs.owner_username,gs.country_key,gs.site_type,sr.quantity,sr.capacity FROM game_sites gs LEFT JOIN site_resources sr ON sr.site_id=gs.id AND sr.resource=? WHERE gs.server=? AND gs.site_type IN ("+rule.warehouseTypes.map(()=>'?').join(',')+") AND gs.integrity>0 ORDER BY gs.id").bind(resource,server,...rule.warehouseTypes).all()).results||[];
      const dedicatedCapacity=resource==='oil'?KOW_TIMING.oilTankCapacity:resource==='steel'?KOW_TIMING.steelWarehouseCapacity:KOW_TIMING.foodWarehouseCapacity;
      const storageCapacity=w=>String(w.site_type)==='warehouse'?GENERIC_WAREHOUSE_RESOURCE_CAPACITY:dedicatedCapacity;
      const missingStorageRows=warehouses.filter(w=>w.capacity==null);
      if(missingStorageRows.length){const init=missingStorageRows.map(w=>env.DB.prepare('INSERT OR IGNORE INTO site_resources(site_id,resource,quantity,capacity,updated_at) VALUES(?,?,0,?,?)').bind(w.id,resource,storageCapacity(w),t));for(let i=0;i<init.length;i+=80)await env.DB.batch(init.slice(i,i+80));}
      const remainingByWarehouse=new Map(warehouses.map(w=>[String(w.id),Math.max(0,Number(w.capacity==null?storageCapacity(w):w.capacity)-Number(w.quantity||0))]));
      const storageByOwnerCountry=new Map();
      for(const w of warehouses){const key=JSON.stringify([String(w.owner_username),String(w.country_key)]);if(!storageByOwnerCountry.has(key))storageByOwnerCountry.set(key,[]);storageByOwnerCountry.get(key).push(w);}
      const ids=matches.map(x=>safeInt(x.id));
      const states=[];for(let offset=0;offset<ids.length;offset+=400){const part=ids.slice(offset,offset+400);const page=(await env.DB.prepare('SELECT site_id,last_tick FROM resource_production_state WHERE resource=? AND site_id IN ('+part.map(()=>'?').join(',')+')').bind(resource,...part).all()).results||[];states.push(...page);}
      const stateById=new Map(states.map(x=>[String(x.site_id),x]));
      const writes=[];
      for(const ind of matches){
        processed++;
        const key=JSON.stringify([String(ind.owner_username),String(ind.country_key)]);
        const tanks=storageByOwnerCountry.get(key)||[];
        const st=stateById.get(String(ind.id));
        if(!st){writes.push(env.DB.prepare('INSERT OR IGNORE INTO resource_production_state(site_id,resource,last_tick) VALUES(?,?,?)').bind(ind.id,resource,t));continue;}
        const usable=tanks.filter(x=>(remainingByWarehouse.get(String(x.id))||0)>0);
        if(!usable.length){writes.push(env.DB.prepare('UPDATE resource_production_state SET last_tick=? WHERE site_id=? AND resource=?').bind(t,ind.id,resource));continue;}
        const lastTick=Math.max(0,safeInt(st.last_tick,t));
        const steps=Math.floor(Math.max(0,t-lastTick)/rule.intervalMs);
        if(steps<=0)continue;
        let remaining=steps*rule.amount;
        for(const tank of usable){
          if(remaining<=0)break;
          const room=remainingByWarehouse.get(String(tank.id))||0;
          const add=Math.min(remaining,room);
          if(add<=0)continue;
          writes.push(env.DB.prepare('UPDATE site_resources SET quantity=MIN(capacity,quantity+?),updated_at=? WHERE site_id=? AND resource=? AND quantity<capacity').bind(add,t,tank.id,resource));
          remaining-=add;remainingByWarehouse.set(String(tank.id),Math.max(0,room-add));produced[resource]+=add;
        }
        // Keep fractional elapsed time; full storage consumes elapsed production, while
        // missing storage pauses production without accumulating an offline backlog.
        writes.push(env.DB.prepare('UPDATE resource_production_state SET last_tick=? WHERE site_id=? AND resource=?').bind(lastTick+steps*rule.intervalMs,ind.id,resource));
      }
      for(let i=0;i<writes.length;i+=80)await env.DB.batch(writes.slice(i,i+80));
    }
    return{ok:true,processed,produced};
  },350);}catch(e){if(String(e&&e.message)==='LOCK_BUSY')return{ok:true,skipped:true,reason:'production_tick_busy'};throw e;}
}
